    { name: "Humanity’s Last Exam", openai: "1", google: "3", anthropic: "", muse: "2" },
    { name: "EnigmaEval", openai: "1", google: "2", anthropic: "", muse: "" },
    { name: "MultiChallenge", openai: "3", google: "2", anthropic: "", muse: "1" },
    { name: "SciPredict", openai: "", google: "1", anthropic: "2", muse: "" },
    // Multimodal
    { name: "AudioMultiCh. (Text)", openai: "", google: "1", anthropic: "", muse: "" },
    { name: "AudioMultiCh. (Audio)", openai: "2", google: "1", anthropic: "", muse: "" },
    { name: "VISTA", openai: "2", google: "1", anthropic: "", muse: "" },
    // Safety
    { name: "MASK (Honesty)", openai: "", google: "", anthropic: "1", muse: "" },
    { name: "Fortress", openai: "", google: "", anthropic: "2", muse: "" },
    { name: "Prof. Reasoning (Legal)", openai: "", google: "", anthropic: "1", muse: "" },
    { name: "Prof. Reasoning (Finance)", openai: "", google: "", anthropic: "1", muse: "2" },
  ];

  function rankCell(rank, labColor) {
    if (rank === "") return { text: "", options: { fill: { color: C.white }, fontSize: 10, fontFace: FONT_MONO, align: "center" } };
    const rankNum = parseInt(rank);
    const alpha = rankNum === 1 ? 1.0 : (rankNum === 2 ? 0.5 : 0.25);
    // Use solid color with opacity indication via fill intensity
    const bgIntensity = rankNum === 1 ? 25 : (rankNum === 2 ? 12 : 5);
    // Approximate light version of color
    let bgColor;
    if (labColor === C.openai) bgColor = rankNum === 1 ? "D1FAE5" : (rankNum === 2 ? "ECFDF5" : "F0FDF4");
    else if (labColor === C.google) bgColor = rankNum === 1 ? "DBEAFE" : (rankNum === 2 ? "EFF6FF" : "F0F7FF");
    else if (labColor === C.anthropic) bgColor = rankNum === 1 ? "FEF3C7" : (rankNum === 2 ? "FFFBEB" : "FEFCE8");
    else bgColor = rankNum === 1 ? "EDE9FE" : (rankNum === 2 ? "F5F3FF" : "FAF5FF");

    return {
      text: "#" + rank,
      options: {
        fill: { color: bgColor },
        fontSize: 10, fontFace: FONT_MONO, align: "center",
        color: rankNum === 1 ? labColor : C.muted,
        bold: rankNum === 1
      }
    };
  }

  // Section header helper
  function sectionHeader(label, color) {
    return [
      { text: label, options: { fill: { color: color }, color: C.textLight, bold: true, fontSize: 9, fontFace: FONT_BODY, align: "left", colspan: 5 } },
    ];
  }

  const tableRows = [headerRow];
  // Agentic section
  tableRows.push(sectionHeader("AGENTIC", C.agentic));
  matrix.slice(0, 5).forEach((row, ri) => {
    const bg = ri % 2 === 0 ? "F8FAFC" : C.white;
    tableRows.push([
      { text: row.name, options: { fill: { color: bg }, fontSize: 9, fontFace: FONT_BODY, color: C.textDark, align: "left" } },
      rankCell(row.openai, C.openai),
      rankCell(row.google, C.google),
      rankCell(row.anthropic, C.anthropic),
      rankCell(row.muse, C.muse),
    ]);
  });
  // Frontier section
  tableRows.push(sectionHeader("FRONTIER", C.frontier));
  matrix.slice(5, 9).forEach((row, ri) => {
    const bg = ri % 2 === 0 ? "F8FAFC" : C.white;
    tableRows.push([
      { text: row.name, options: { fill: { color: bg }, fontSize: 9, fontFace: FONT_BODY, color: C.textDark, align: "left" } },
      rankCell(row.openai, C.openai),
      rankCell(row.google, C.google),
      rankCell(row.anthropic, C.anthropic),
      rankCell(row.muse, C.muse),
    ]);
  });
  // Multimodal section
  tableRows.push(sectionHeader("MULTIMODAL", C.multimodal));
  matrix.slice(9, 12).forEach((row, ri) => {
    const bg = ri % 2 === 0 ? "F8FAFC" : C.white;
    tableRows.push([
      { text: row.name, options: { fill: { color: bg }, fontSize: 9, fontFace: FONT_BODY, color: C.textDark, align: "left" } },
      rankCell(row.openai, C.openai),
      rankCell(row.google, C.google),
      rankCell(row.anthropic, C.anthropic),
      rankCell(row.muse, C.muse),
    ]);
  });
  // Safety section
  tableRows.push(sectionHeader("SAFETY", C.safety));
  matrix.slice(12).forEach((row, ri) => {
    const bg = ri % 2 === 0 ? "F8FAFC" : C.white;
    tableRows.push([
      { text: row.name, options: { fill: { color: bg }, fontSize: 9, fontFace: FONT_BODY, color: C.textDark, align: "left" } },
      rankCell(row.openai, C.openai),
      rankCell(row.google, C.google),
      rankCell(row.anthropic, C.anthropic),
      rankCell(row.muse, C.muse),
    ]);
  });

  slide.addTable(tableRows, {
    x: 0.4, y: 1.05, w: 9.2,
    colW: [2.5, 1.5, 1.5, 1.5, 1.5],
    border: { pt: 0.5, color: C.border },
    rowH: [0.3, 0.22],
  });

  // Footer
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.1, w: 10, h: 0.525, fill: { color: C.darkBg2 }
  });
  slide.addText("Scale SEAL Leaderboards  |  No single lab wins across all domains — specialization is the defining trend", {
    x: 0.6, y: 5.15, w: 8.8, h: 0.4,
    fontSize: 9, fontFace: FONT_BODY, color: "94A3B8", margin: 0
  });
}

// ═══════════════════════════════════════════════════════════
// SLIDE 8: Key Takeaways
// ═══════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.darkBg };

  // Top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.accent }
  });

  // Title
  slide.addText("Key Takeaways", {
    x: 0.7, y: 0.3, w: 8.6, h: 0.6,
    fontSize: 30, fontFace: FONT_HEAD, color: C.textLight, bold: true, margin: 0
  });
  slide.addText("No Single Model Wins Everything — Specialization Is the New Frontier", {
    x: 0.7, y: 0.85, w: 8.6, h: 0.4,
    fontSize: 16, fontFace: FONT_BODY, color: "94A3B8", italic: true, margin: 0
  });

  const takeaways = [
    {
      number: "01",
      text: "GPT-5.4 leads agentic coding and frontier reasoning, but does not compete in multimodal or safety domains.",
      color: C.openai,
    },
    {
      number: "02",
      text: "Gemini dominates audio and vision-language benchmarks, sweeping all top-3 positions on AudioMultiChallenge (Text Output).",
      color: C.google,
    },
    {
      number: "03",
      text: "Claude leads safety alignment (96%+ on MASK) and professional reasoning (Legal, Finance), but Fortress scores remain critically low across all models.",
      color: C.anthropic,
    },
    {
      number: "04",
      text: "Key benchmarks remain unsaturated: HLE (44%), EnigmaEval (24%), SciPredict (25%) — substantial room for improvement.",
      color: C.safety,
    },
    {
      number: "05",
      text: "New entrant Muse Spark ranks top 3 on 6+ benchmarks spanning coding, tool use, and reasoning — including #1 on MultiChallenge at 75.5%.",
      color: C.muse,
    },
  ];

  takeaways.forEach((t, i) => {
    const ty = 1.5 + i * 0.72;

    // Number circle
    slide.addShape(pres.shapes.OVAL, {
      x: 0.7, y: ty, w: 0.42, h: 0.42,
      fill: { color: t.color }
    });
    slide.addText(t.number, {
      x: 0.7, y: ty, w: 0.42, h: 0.42,
      fontSize: 12, fontFace: FONT_HEAD, color: C.textLight, bold: true,
      align: "center", valign: "middle", margin: 0
    });

    // Text
    slide.addText(t.text, {
      x: 1.3, y: ty, w: 8.0, h: 0.42,
      fontSize: 13, fontFace: FONT_BODY, color: "CBD5E1", margin: 0, valign: "middle"
    });
  });

  // Bottom bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.1, w: 10, h: 0.525, fill: { color: C.darkBg2 }
  });
  slide.addText("Scale Labs  |  leaderboard.scale.com  |  Data as of 2025", {
    x: 0.7, y: 5.15, w: 8.6, h: 0.4,
    fontSize: 10, fontFace: FONT_BODY, color: "64748B", margin: 0
  });
}

// ── Write File ──
const outPath = "/app/output/final_deck.pptx";
pres.writeFile({ fileName: outPath }).then(() => {
  console.log("Deck saved to " + outPath);
}).catch(err => {
  console.error("Error:", err);
  process.exit(1);
});

