const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Scale Labs";
pres.title = "Scale SEAL Leaderboards: Frontier Model Performance Across 20+ Benchmarks";

// ── Color Palette ──
const C = {
  darkBg:     "0F172A",
  darkBg2:    "1E293B",
  lightBg:    "F8FAFC",
  white:      "FFFFFF",
  cardBg:     "FFFFFF",
  textDark:   "1E293B",
  textLight:  "F8FAFC",
  muted:      "64748B",
  border:     "E2E8F0",
  accent:     "3B82F6",
  openai:     "10B981",
  google:     "3B82F6",
  anthropic:  "F59E0B",
  muse:       "8B5CF6",
  agentic:    "10B981",
  frontier:   "3B82F6",
  safety:     "EF4444",
  multimodal: "8B5CF6",
};

const FONT_HEAD = "Arial Black";
const FONT_BODY = "Calibri";
const FONT_MONO = "Consolas";

function makeShadow() {
  return { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.10 };
}
function makeCardShadow() {
  return { type: "outer", blur: 6, offset: 3, angle: 135, color: "000000", opacity: 0.12 };
}

// ═══════════════════════════════════════════════════════════
// SLIDE 1: Title
// ═══════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.darkBg };

  // Top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.accent }
  });

  // Domain color strips (left side) — larger and more spaced
  const strips = [
    { color: C.agentic,    y: 1.5 },
    { color: C.frontier,   y: 1.85 },
    { color: C.safety,     y: 2.2 },
    { color: C.multimodal, y: 2.55 },
  ];
  strips.forEach(s => {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.7, y: s.y, w: 0.12, h: 0.25, fill: { color: s.color }
    });
  });

  // Title
  slide.addText("Scale SEAL Leaderboards", {
    x: 1.1, y: 1.2, w: 8, h: 0.8,
    fontSize: 40, fontFace: FONT_HEAD, color: C.textLight,
    bold: true, margin: 0
  });

  // Subtitle
  slide.addText("Frontier Model Performance Across 20+ Benchmarks", {
    x: 1.1, y: 2.15, w: 8, h: 0.5,
    fontSize: 22, fontFace: FONT_BODY, color: "94A3B8", margin: 0
  });

  // Description line
  slide.addText("100+ models evaluated  |  Agentic  |  Frontier  |  Safety  |  Multimodal", {
    x: 1.1, y: 2.85, w: 8, h: 0.35,
    fontSize: 13, fontFace: FONT_BODY, color: "64748B", margin: 0
  });

  // Bottom bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.0, w: 10, h: 0.625, fill: { color: C.darkBg2 }
  });
  slide.addText("Scale Labs  |  leaderboard.scale.com", {
    x: 1.1, y: 5.1, w: 8, h: 0.35,
    fontSize: 11, fontFace: FONT_BODY, color: "64748B", margin: 0
  });
}

// ═══════════════════════════════════════════════════════════
// SLIDE 2: Benchmark Landscape Overview
// ═══════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  // Title
  slide.addText("20+ Benchmarks Spanning Four Capability Domains Evaluate 100+ Models", {
    x: 0.6, y: 0.3, w: 8.8, h: 0.7,
    fontSize: 22, fontFace: FONT_HEAD, color: C.textDark, bold: true, margin: 0
  });

  const domains = [
    {
      title: "AGENTIC", color: C.agentic,
      benchmarks: ["SWE Atlas – Test Writing", "SWE Atlas – Codebase QnA", "MCP Atlas (Tool Use)", "SWE-Bench Pro (Public)", "SWE-Bench Pro (Private)"],
      leader: "GPT-5.4 leads",
    },
    {
      title: "FRONTIER", color: C.frontier,
      benchmarks: ["Humanity's Last Exam", "EnigmaEval", "MultiChallenge", "MultiNRC", "SciPredict"],
      leader: "GPT-5.4 / Muse Spark",
    },
    {
      title: "SAFETY", color: C.safety,
      benchmarks: ["MASK (Honesty)", "PropensityBench", "Fortress (Nat'l Security)", "Prof. Reasoning – Legal", "Prof. Reasoning – Finance"],
      leader: "Claude dominates",
    },
    {
      title: "MULTIMODAL", color: C.multimodal,
      benchmarks: ["AudioMultiChallenge (Text)", "AudioMultiChallenge (Audio)", "VISTA (Vision-Language)", "VisualToolBench"],
      leader: "Gemini sweeps",
    },
  ];

  const cardW = 2.1;
  const cardH = 3.2;
  const gap = 0.15;
  const startX = 0.5;
  const startY = 1.15;

  domains.forEach((d, i) => {
    const cx = startX + i * (cardW + gap);

    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: startY, w: cardW, h: cardH,
      fill: { color: C.white }, shadow: makeCardShadow()
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: startY, w: cardW, h: 0.06, fill: { color: d.color }
    });
    slide.addText(d.title, {
      x: cx + 0.15, y: startY + 0.2, w: cardW - 0.3, h: 0.3,
      fontSize: 13, fontFace: FONT_HEAD, color: d.color, bold: true, margin: 0
    });
    slide.addText(d.leader, {
      x: cx + 0.15, y: startY + 0.5, w: cardW - 0.3, h: 0.22,
      fontSize: 9, fontFace: FONT_BODY, color: C.muted, italic: true, margin: 0
    });

    const benchText = d.benchmarks.map(b => ({
      text: b,
      options: { bullet: true, breakLine: true, fontSize: 10, fontFace: FONT_BODY, color: C.textDark }
    }));
    slide.addText(benchText, {
      x: cx + 0.15, y: startY + 0.85, w: cardW - 0.3, h: cardH - 1.0,
      margin: [0, 0, 0, 0], paraSpaceAfter: 3
    });
  });

  // Footer
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.0, w: 10, h: 0.625, fill: { color: C.darkBg2 }
  });
  slide.addText("Scale SEAL Leaderboards  |  20+ benchmarks  |  100+ models  |  Confidence intervals on all scores", {
    x: 0.6, y: 5.1, w: 8.8, h: 0.35,
    fontSize: 9, fontFace: FONT_BODY, color: "94A3B8", margin: 0
  });
}

// ═══════════════════════════════════════════════════════════
// SLIDE 3: Agentic Coding Leaders
// ═══════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  // Title
  slide.addText("GPT-5.4 Dominates Agentic Coding: Top Scores on SWE Atlas and SWE-Bench Pro", {
    x: 0.6, y: 0.3, w: 8.8, h: 0.65,
    fontSize: 20, fontFace: FONT_HEAD, color: C.textDark, bold: true, margin: 0
  });

  // Legend
  const legendItems = [
    { label: "OpenAI", color: C.openai },
    { label: "Anthropic", color: C.anthropic },
    { label: "Muse Spark", color: C.muse },
    { label: "Google", color: C.google },
  ];
  legendItems.forEach((item, i) => {
    const lx = 0.6 + i * 1.5;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: lx, y: 1.1, w: 0.18, h: 0.18, fill: { color: item.color }
    });
    slide.addText(item.label, {
      x: lx + 0.25, y: 1.08, w: 1.1, h: 0.22,
      fontSize: 10, fontFace: FONT_BODY, color: C.textDark, margin: 0
    });
  });

  // Table
  const headerRow = [
    { text: "Benchmark", options: { fill: { color: C.darkBg }, color: C.textLight, bold: true, fontSize: 10, fontFace: FONT_BODY, align: "left" } },
    { text: "#1 Model", options: { fill: { color: C.darkBg }, color: C.textLight, bold: true, fontSize: 10, fontFace: FONT_BODY, align: "left" } },
    { text: "Score", options: { fill: { color: C.darkBg }, color: C.textLight, bold: true, fontSize: 10, fontFace: FONT_BODY, align: "center" } },
    { text: "#2 Model", options: { fill: { color: C.darkBg }, color: C.textLight, bold: true, fontSize: 10, fontFace: FONT_BODY, align: "left" } },
    { text: "Score", options: { fill: { color: C.darkBg }, color: C.textLight, bold: true, fontSize: 10, fontFace: FONT_BODY, align: "center" } },
    { text: "#3 Model", options: { fill: { color: C.darkBg }, color: C.textLight, bold: true, fontSize: 10, fontFace: FONT_BODY, align: "left" } },
    { text: "Score", options: { fill: { color: C.darkBg }, color: C.textLight, bold: true, fontSize: 10, fontFace: FONT_BODY, align: "center" } },
  ];

  function labColor(model) {
    if (model.includes("GPT") || model.includes("Codex")) return C.openai;
    if (model.includes("Claude") || model.includes("Opus")) return C.anthropic;
    if (model.includes("Muse")) return C.muse;
    if (model.includes("Gemini")) return C.google;
    return C.muted;
  }

  const data = [
    ["SWE Atlas – Test Writing", "GPT-5.4-xHigh (Codex CLI)", "44.36", "GPT-5.4-xHigh (Mini-SWE)", "40.00", "GPT-5.3-Codex-Xhigh", "38.98"],
    ["SWE Atlas – Codebase QnA", "GPT 5.4 xHigh (Codex)", "40.80", "GPT 5.4 xHigh (Mini-SWE)", "36.30", "Opus 4.6 (Claude Code)", "33.30"],
    ["MCP Atlas (Tool Use)", "Muse Spark", "78.30", "Claude Opus 4.6", "75.80", "Gemini 3.1 Pro Preview", "73.90"],
    ["SWE-Bench Pro (Public)", "GPT-5.4-pro (xHigh)", "59.10", "Muse Spark", "55.00", "Claude Opus 4.6", "51.90"],
    ["SWE-Bench Pro (Private)", "Claude Opus 4.6", "47.10", "Muse Spark", "44.70", "GPT-5.4-pro (xHigh)", "43.40"],
  ];

  const tableRows = [headerRow];
  data.forEach((row, ri) => {
    const bgColor = ri % 2 === 0 ? "F1F5F9" : C.white;
    const cells = [
      { text: row[0], options: { fill: { color: bgColor }, fontSize: 9, fontFace: FONT_BODY, color: C.textDark, bold: true, align: "left" } },
      { text: row[1], options: { fill: { color: bgColor }, fontSize: 9, fontFace: FONT_BODY, color: labColor(row[1]), align: "left" } },
      { text: row[2], options: { fill: { color: bgColor }, fontSize: 9, fontFace: FONT_MONO, color: C.textDark, align: "center", bold: true } },
      { text: row[3], options: { fill: { color: bgColor }, fontSize: 9, fontFace: FONT_BODY, color: labColor(row[3]), align: "left" } },
      { text: row[4], options: { fill: { color: bgColor }, fontSize: 9, fontFace: FONT_MONO, color: C.textDark, align: "center" } },
      { text: row[5], options: { fill: { color: bgColor }, fontSize: 9, fontFace: FONT_BODY, color: labColor(row[5]), align: "left" } },
      { text: row[6], options: { fill: { color: bgColor }, fontSize: 9, fontFace: FONT_MONO, color: C.textDark, align: "center" } },
    ];
    tableRows.push(cells);
  });

  slide.addTable(tableRows, {
    x: 0.5, y: 1.45, w: 9.0,
    colW: [1.8, 1.7, 0.7, 1.7, 0.7, 1.5, 0.7],
    border: { pt: 0.5, color: C.border },
    rowH: [0.32, 0.35, 0.35, 0.35, 0.35, 0.35],
  });

  // Key insight callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 3.7, w: 8.8, h: 0.7,
    fill: { color: "ECFDF5" }, shadow: makeShadow()
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 3.7, w: 0.06, h: 0.7, fill: { color: C.agentic }
  });
  slide.addText([
    { text: "Key Insight: ", options: { bold: true, fontSize: 11, fontFace: FONT_BODY, color: "065F46" } },
    { text: "GPT-5.4 leads 4 of 5 agentic benchmarks, but Claude Opus 4.6 takes #1 on SWE-Bench Pro (Private). Muse Spark appears in top 3 on 3 of 5 benchmarks.", options: { fontSize: 11, fontFace: FONT_BODY, color: "065F46" } },
  ], { x: 0.85, y: 3.73, w: 8.4, h: 0.64, margin: 0, valign: "middle" });

  // Footer
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.0, w: 10, h: 0.625, fill: { color: C.darkBg2 }
  });
  slide.addText("Scale SEAL Leaderboards  |  All scores include confidence intervals", {
    x: 0.6, y: 5.1, w: 8.8, h: 0.35,
    fontSize: 9, fontFace: FONT_BODY, color: "94A3B8", margin: 0
  });
}

// ═══════════════════════════════════════════════════════════
// SLIDE 4: Frontier Reasoning Rankings (2x2 chart grid)
// ═══════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  slide.addText("GPT-5.4-Pro Leads Humanity's Last Exam at 44.3% — Scores Remain Below 50%", {
    x: 0.6, y: 0.25, w: 8.8, h: 0.6,
    fontSize: 20, fontFace: FONT_HEAD, color: C.textDark, bold: true, margin: 0
  });

  const chartOpts = {
    barDir: "bar",
    showValue: true, dataLabelPosition: "outEnd", dataLabelColor: C.textDark, dataLabelFontSize: 9,
    catAxisLabelColor: C.muted, catAxisLabelFontSize: 9,
    valAxisHidden: true,
    valGridLine: { color: C.border, size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    chartArea: { fill: { color: C.white }, roundedCorners: true },
  };

  // Top-left: HLE
  slide.addChart(pres.charts.BAR, [
    { name: "GPT-5.4-pro", labels: ["Score"], values: [44.32] },
    { name: "Muse Spark", labels: ["Score"], values: [40.56] },
    { name: "Gemini-3-pro-preview", labels: ["Score"], values: [37.52] },
