    { name: "Fortress", domain: C.safety, openai: "", google: "", anthropic: "2", muse: "" },
    { name: "Prof. Reasoning (Legal)", domain: C.safety, openai: "", google: "", anthropic: "1", muse: "" },
    { name: "Prof. Reasoning (Finance)", domain: C.safety, openai: "", google: "", anthropic: "1", muse: "2" },
  ];

  const tableRows = [headerRow];
  matrix.forEach((row, ri) => {
    const bg = ri % 2 === 0 ? "F8FAFC" : C.white;
    tableRows.push([
      { text: row.name, options: { fill: { color: bg }, fontSize: 8, fontFace: FONT_BODY, color: row.domain, bold: true, align: "left" } },
      rankCell(row.openai, C.openai),
      rankCell(row.google, C.google),
      rankCell(row.anthropic, C.anthropic),
