const headerRow = [
  { text: "Benchmark", options: { fill: { color: C.darkBg }, color: C.textLight, bold: true, fontSize: 8, fontFace: FONT_BODY, align: "left" } },
  { text: "OpenAI", options: { fill: { color: C.darkBg }, color: C.openai, bold: true, fontSize: 8, fontFace: FONT_BODY, align: "center" } },
  { text: "Google", options: { fill: { color: C.darkBg }, color: C.google, bold: true, fontSize: 8, fontFace: FONT_BODY, align: "center" } },
  { text: "Anthropic", options: { fill: { color: C.darkBg }, color: C.anthropic, bold: true, fontSize: 8, fontFace: FONT_BODY, align: "center" } },
  { text: "Muse Spark", options: { fill: { color: C.darkBg }, color: C.muse, bold: true, fontSize: 8, fontFace: FONT_BODY, align: "center" } },
];

function rankCell(rank, labColor) {
  if (rank === "") return { text: "—", options: { fill: { color: C.white }, fontSize: 8, fontFace: FONT_MONO, align: "center", color: "CBD5E1" } };
  const rankNum = parseInt(rank);
  let bgColor;
  if (labColor === C.openai) bgColor = rankNum === 1 ? "D1FAE5" : (rankNum === 2 ? "ECFDF5" : "F0FDF4");
  else if (labColor === C.google) bgColor = rankNum === 1 ? "DBEAFE" : (rankNum === 2 ? "EFF6FF" : "F0F7FF");
  else if (labColor === C.anthropic) bgColor = rankNum === 1 ? "FEF3C7" : (rankNum === 2 ? "FFFBEB" : "FEFCE8");
  else bgColor = rankNum === 1 ? "EDE9FE" : (rankNum === 2 ? "F5F3FF" : "FAF5FF");
  return {
    text: "#" + rank,
    options: {
      fill: { color: bgColor },
      fontSize: 9, fontFace: FONT_MONO, align: "center",
      color: rankNum === 1 ? labColor : C.muted,
      bold: rankNum === 1
    }
  };
}

